// Payments paid yesterday in this workflow's time zone (workflow Settings → Timezone), totalled per currency.
// Railbed sends amounts as decimal text such as "49.00", so they're added up in cents, and different currencies are
// never added together. The list holds paid payments created in the last week, because a payment can be paid after
// the day it was created; paid_at decides which day it counts for.
const from = $today.minus({ days: 1 }).toSeconds();
const to = $today.toSeconds();
const cents = {};
let count = 0;
for (const { json: payment } of $input.all()) {
  if (payment.status !== 'paid' || typeof payment.paid_at !== 'number') continue;
  if (payment.paid_at < from || payment.paid_at >= to) continue;
  const [whole, fraction = ''] = String(payment.amount).split('.');
  const value = Number(whole) * 100 + Number(fraction.padEnd(2, '0').slice(0, 2));
  cents[payment.currency] = (cents[payment.currency] ?? 0) + value;
  count++;
}
const totals = Object.entries(cents)
  .sort(([, a], [, b]) => b - a)
  .map(([currency, value]) => ({ currency, amount: `${Math.floor(value / 100)}.${String(value % 100).padStart(2, '0')}` }));
const day = $today.minus({ days: 1 }).toFormat('d LLL yyyy');
const summary = count
  ? `${count} paid ${count === 1 ? 'payment' : 'payments'} on ${day}: ${totals.map((t) => `${t.amount} ${t.currency}`).join(', ')}.`
  : `No payments were paid on ${day}.`;
return [{ json: { day, count, totals, summary } }];
